using System;
using UnityEngine;

namespace Echoes
{
    /// <summary>
    /// Frames of a 2.5D character in one atlas (generated by tools/art/phase52b3 from the owner's illustrations): per facing direction a run
    /// cycle and an idle loop, the ground pivot of every frame, the texel scale and the distance the run cycle covers.
    /// </summary>
    [CreateAssetMenu(menuName = "Echoes/Sprite Sheet 2.5D")]
    public sealed class SpriteSheet25D : ScriptableObject
    {
        [Serializable]
        public struct Frame
        {
            public Vector4 uv;       // x, y, width, height in atlas UV space
            public Vector2 sizePx;   // frame size in texels
        }

        [Serializable]
        public sealed class Direction
        {
            public string key;           // S (facing the camera), N (facing away), W (facing screen-left), E (facing screen-right)
            public Vector2 pivotPx;      // ground point under the pelvis, from the frame's bottom-left corner
            public Frame[] run = Array.Empty<Frame>();
            public Frame[] idle = Array.Empty<Frame>();
            public string mirrorOf = "";  // E is W drawn mirrored
            public float phaseOffset;     // run phase shift that keeps the same leg planted when the mirror swaps sides
        }

        public Texture2D atlas;
        public float pixelsPerMeter = 289f;
        public float strideMeters = 2.85f;
        public float idleFps = 8f;
        public Direction[] directions = Array.Empty<Direction>();

        public Direction Get(string key)
        {
            foreach (Direction d in directions)
                if (d.key == key) return d;
            return null;
        }

        /// <summary>The direction whose frames are drawn for <paramref name="key"/> (E resolves to W), and whether to mirror them.</summary>
        public Direction Resolve(string key, out bool mirrored, out float phaseOffset)
        {
            Direction d = Get(key);
            mirrored = false;
            phaseOffset = 0f;
            if (d != null && !string.IsNullOrEmpty(d.mirrorOf))
            {
                mirrored = true;
                phaseOffset = d.phaseOffset;
                d = Get(d.mirrorOf);
            }
            return d;
        }
    }
}
